INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'eg-law-2020', id, '2020-11-15', 1, 'https://www.eta.gov.eg', 0, '[]', NULL FROM countries WHERE code = 'EG';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-law-2020', 'en', 'Unified Tax Procedures Law and first e-invoicing wave', 'Law No. 206 of 2020 established the legal basis for Egypt''s electronic invoicing regime, giving electronic signatures the same legal weight as handwritten ones. The first wave of large taxpayers registered with the ETA''s Large Taxpayers Centre began mandatory electronic invoicing in November 2020, opening a phased rollout that would eventually reach every VAT-registered business.', '["Historical context — no action needed"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'eg-einvoicing-all', id, '2023-04-01', 0, 'https://invoicing.eta.gov.eg', 1, '[{"label": "ETA e-invoicing portal", "url": "https://invoicing.eta.gov.eg"}, {"label": "Egyptian Tax Authority", "url": "https://www.eta.gov.eg"}]', NULL FROM countries WHERE code = 'EG';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-einvoicing-all', 'en', 'B2B/B2G e-invoicing mandatory for all VAT-registered businesses (in force since April 2023)', 'Egypt operates a centralized clearance model: invoices are issued in structured JSON/XML, digitally signed, and submitted to the Egyptian Tax Authority''s central platform in real or near-real time. The phased rollout that began with large taxpayers in November 2020 reached all VAT-registered businesses by April 2023, and from July 2023 paper invoices are no longer recognized for VAT deduction — only ETA-cleared electronic invoices support input VAT recovery.', '["Ensure all Egyptian entities issue via the ETA platform — paper invoices no longer support VAT deduction", "Verify digital signature certificates and standardized product coding (GS1/EGS) are in place"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'eg-ereceipt-wave8', id, '2025-09-15', 0, 'https://www.eta.gov.eg', 1, '[{"label": "Egyptian Tax Authority", "url": "https://www.eta.gov.eg"}]', NULL FROM countries WHERE code = 'EG';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-ereceipt-wave8', 'en', 'E-receipt system: eighth sub-phase of B2C rollout (in force since September 2025)', 'Decision No. 281 of 2025 brought an additional group of taxpayers into Egypt''s electronic receipt system — the eighth sub-phase of the second stage of the B2C rollout. Obligated businesses must integrate their point-of-sale devices or ERP systems with the ETA''s central platform so consumer transactions can be verified in real time, and can check whether they are in scope via the ETA''s dedicated lookup page.', '["Check the ETA lookup page to confirm whether your Egyptian retail operations are in scope", "Integrate POS or ERP systems with the ETA central platform for real-time receipt verification"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'eg-enforcement-2026', id, '2026-01-01', 0, 'https://www.eta.gov.eg', 1, '[{"label": "ETA e-invoicing portal", "url": "https://invoicing.eta.gov.eg"}]', NULL FROM countries WHERE code = 'EG';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-enforcement-2026', 'en', '2026 enforcement stage: late-submission penalties and QR codes on printed e-receipts', 'From 1 January 2026 the ETA moved into the enforcement stage of the rollout that began in 2020. An explicit penalty regime now applies to late submission of e-invoices and e-receipts, every printed e-receipt must display a QR code linking back to the validated record in the ETA portal, and a tiered enforcement framework can ultimately suspend a non-compliant business''s ability to issue valid invoices. Non-compliance can also mean denial of VAT input credits, exclusion from government contracts, and import/export restrictions.', '["Audit submission timeliness — late e-invoice and e-receipt filings now attract explicit penalties", "Confirm printed e-receipts carry the QR code linking to the validated ETA record"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'eg-threshold-250k', id, '2026-03-31', 0, 'https://www.eta.gov.eg', 1, '[{"label": "Egyptian Tax Authority", "url": "https://www.eta.gov.eg"}]', NULL FROM countries WHERE code = 'EG';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-threshold-250k', 'en', 'Registration threshold lowered to EGP 250,000 — registration deadline passed 31 March 2026', 'The ETA''s expanded registration requirements cut the mandatory e-invoicing registration threshold from EGP 500,000 to EGP 250,000 in gross annual revenue, drawing many previously exempt small businesses into the system. Businesses above the threshold were required to register with the ETA by 31 March 2026; missing the deadline triggers an EGP 20,000 fine plus an EGP 1,000 daily penalty. The threshold is measured on gross revenue before expenses, and the ETA cross-references VAT filings against exemption claims automatically.', '["If gross 2025 revenue of an Egyptian entity exceeded EGP 250,000, verify its ETA registration status immediately — daily penalties accrue", "Review smaller subsidiaries and sole-trader arrangements previously below the old EGP 500,000 threshold"]');
